def find_second_largest(numbers):
    if len(numbers) < 2:
        return None  # Not enough elements to determine the second largest

    first = second = float('-inf')

    for num in numbers:
        if num > first:
            second = first
            first = num
        elif first > num > second:
            second = num

    return second if second != float('-inf') else None

